mapper.select:
select tallot.id, tallot.code, tallot.material_id, tallot.batch_code, tallot.allot_num, tallot.out_warehouse_id, tallot.out_warehouse_name, tallot.in_warehouse_id, tallot.in_warehouse_name, tallot.allot_status, tallot.auditor, tallot.create_by, tallot.create_time, tallot.update_by, tallot.update_time, tallot.dept_id, tallot.dept_name, tallot.del_flag
,material.name as material_name,unit.name as unit_name,material.code as material_code
from t_allot tallot

    inner join sys_user u on u.user_name = tallot.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'

left join t_material material on tallot.material_id = material.id
left join t_unit unit on unit.id = material.unit_id

    tallot.del_flag = '0'
     and tallot.code like concat('%', #{code}, '%')
     and tallot.material_id = #{materialId}
     and tallot.batch_code like concat('%', #{batchCode}, '%')
     and tallot.allot_num = #{allotNum}
     and tallot.out_warehouse_id = #{outWarehouseId}
     and tallot.out_warehouse_name like concat('%', #{outWarehouseName}, '%')
     and tallot.in_warehouse_id = #{inWarehouseId}
     and tallot.in_warehouse_name like concat('%', #{inWarehouseName}, '%')
     and tallot.allot_status = #{allotStatus}
     and tallot.auditor = #{auditor}


${params.dataScope}
